-- MommaBees Appearance Settings. All defaults are NULL so the current design is retained.
alter table public.site_settings add column if not exists header_text_color text;
alter table public.site_settings add column if not exists header_background_color text;
alter table public.site_settings add column if not exists footer_text_color text;
alter table public.site_settings add column if not exists footer_background_color text;
alter table public.site_settings add column if not exists category_button_bg_color text;
alter table public.site_settings add column if not exists category_button_text_color text;
alter table public.site_settings add column if not exists tab_selected_bg_color text;
alter table public.site_settings add column if not exists tab_selected_text_color text;
alter table public.site_settings add column if not exists tab_unselected_bg_color text;
alter table public.site_settings add column if not exists tab_unselected_text_color text;
alter table public.site_settings add column if not exists header_background_image_url text;
alter table public.site_settings add column if not exists footer_background_image_url text;
alter table public.site_settings add column if not exists header_font_family text;
alter table public.site_settings add column if not exists footer_font_family text;
alter table public.site_settings add column if not exists category_cta_label text;
alter table public.site_settings add constraint header_text_color_safe_color check (header_text_color is null or header_text_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint header_background_color_safe_color check (header_background_color is null or header_background_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint footer_text_color_safe_color check (footer_text_color is null or footer_text_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint footer_background_color_safe_color check (footer_background_color is null or footer_background_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint category_button_bg_color_safe_color check (category_button_bg_color is null or category_button_bg_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint category_button_text_color_safe_color check (category_button_text_color is null or category_button_text_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint tab_selected_bg_color_safe_color check (tab_selected_bg_color is null or tab_selected_bg_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint tab_selected_text_color_safe_color check (tab_selected_text_color is null or tab_selected_text_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint tab_unselected_bg_color_safe_color check (tab_unselected_bg_color is null or tab_unselected_bg_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint tab_unselected_text_color_safe_color check (tab_unselected_text_color is null or tab_unselected_text_color ~ '^#[[:xdigit:]]{6}$') not valid;
alter table public.site_settings add constraint header_font_family_allowlist check (header_font_family is null or header_font_family in ('Trebuchet MS','Georgia','Arial','Verdana','Tahoma','Segoe UI')) not valid;
alter table public.site_settings add constraint footer_font_family_allowlist check (footer_font_family is null or footer_font_family in ('Trebuchet MS','Georgia','Arial','Verdana','Tahoma','Segoe UI')) not valid;
alter table public.site_settings add constraint category_cta_label_limit check (category_cta_label is null or char_length(category_cta_label) between 1 and 48) not valid;